it("payout calculation yielding 350.5 G → rounded down to 350 G", () => {
  // Dragon-material sword with 801 G damage: dragon full reimbursement, then deductible = 701 G
  // But we need 350.5 to test rounding. Use enchantment ≥ 8: 50% of 801 = 400.5, minus 100 = 300.5
  // Try 901 damage on ench-8 sword: 450.5 - 100 = 350.5 → 350
  const result = runScenario({
    customer: { yearsWithMHPCO: 0 },
    steps: [
      { op: "quote", items: [{ type: "sword", enchantment: 8 }] },
      {
        op: "claim",
        policy: 0,
        incident: { cause: "fire", damages: [{ itemType: "sword", amount: 901 }] },
      },
    ],
  });
  expect(result).toEqual({
    results: [{ premium: 143 }, { payout: 350, remainingCap: 1650 }],
  });
});

