154	  const itemCounts = countBy(items, (i) => i.type);
155	  const damageCounts = countBy(damages, (d) => d.itemType);
156	  for (const [type, count] of damageCounts) {
157	    if (count > (itemCounts.get(type) ?? 0)) {
158	      throw new Error(`more damages of type ${type} than insured`);
159	    }
160	  }
161	};
162	
163	const claimPayout = (damages: Damage[], policy: Policy): number => {
164	  assertDamageCounts(damages, policy.items);
165	  const rawPayout = sumBy(damages, (d) => damagePayout(d, policy.items));
166	  return Math.min(Math.floor(rawPayout), policy.remainingCap);
167	};
168	
169	const handleClaim = ({ policy: policyIndex, incident }: ClaimStep, policies: Policy[]) => {
170	  const policy = policies[policyIndex];
171	  const payout = claimPayout(incident.damages, policy);
172	  policy.remainingCap -= payout;
173	  return { payout, remainingCap: policy.remainingCap };
174	};
175	
176	export const runScenario = ({ customer, steps }: Scenario): unknown => {
177	  const policies: Policy[] = [];
178	  const results = steps.map((step) =>
179	    step.op === "quote" ? handleQuote(step, customer, policies) : handleClaim(step, policies),
180	  );
181	  return { results };
182	};

